use std::io::{Error, ErrorKind, Read, Result, Seek};

use super::TraceHeaderType;
use uuid::Uuid;

const MODERN_EVENT_HEADER_SIZE: usize = 80;

/// A modern event
///
/// Usually a event produced by a manifest based provider.
///
/// Since the API is backwards compatible, modern events can
/// also be generated by other providers (MOF based).
pub struct ModernEvent {
    pub header: ModernEventHeader,
    pub extended_header: Vec<u8>,
    pub payload: Vec<u8>,
}

/// Header of a modern event
#[repr(C)]
pub struct ModernEventHeader {
    pub size: u16,
    pub header_type: TraceHeaderType,
    pub flags: u8,
    pub event_flags: u16,
    pub event_properties: u16,
    pub thread_id: u32,
    pub process_id: u32,
    pub timestamp: u64,
    pub provider_id: Uuid,
    pub event_descriptor: EventDescriptor,
    /// Placeholder for the union describing kernel or processor time
    pub time_union: u64,
    pub activity_id: Uuid,
}

/// WIP Placeholder
pub struct EventDescriptor(u128);

impl ModernEventHeader {
    pub fn parse<T: Read + Seek>(buf: &mut T) -> Result<ModernEventHeader> {
        let mut bytes = [0; MODERN_EVENT_HEADER_SIZE];
        buf.read_exact(&mut bytes)?;
        let size = u16::from_le_bytes(bytes[0..2].try_into().unwrap());

        let header_type = TraceHeaderType::try_from(bytes[2]).map_err(|_| {
            Error::new(
                ErrorKind::InvalidData,
                "encountered unknown TraceHeaderType!",
            )
        })?;

        if !matches!(
            header_type,
            TraceHeaderType::System32
                | TraceHeaderType::System64
                | TraceHeaderType::Compact32
                | TraceHeaderType::Compact64
        ) {
            return Err(Error::new(
                ErrorKind::InvalidData,
                "trying to parse SystemTraceEventHeader, but found other TraceHeaderType!",
            ));
        }

        todo!()
    }
}
